"use strict";
const path = require("path");
// The frames inside this package, by path below it: where the package is
// on the machine is the only part of a frame that is not the program's.
function frames(error) {
  return String(error.stack)
    .split("\n")
    .filter((line) => line.includes(__dirname))
    .map((line) => line.trim().split(__dirname + path.sep).join(""))
    .join(" | ");
}
exports.load = function load() {
  try {
    require("./bad");
    return "loaded";
  } catch (error) {
    return `${error.name}: ${error.message} [${frames(error)}]`;
  }
};
exports.cached = function cached() {
  return Object.keys(require.cache).filter((file) => file.endsWith("bad.js")).length;
};
exports.must = function must() {
  return require("./bad").value;
};
